import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '예산·회계 담당자';
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function textOf(v: unknown): string {
  return typeof v === 'string' ? v.trim() : '';
}

function wholeOf(v: unknown): number | null {
  const s = textOf(v);
  if (s === '') return null;
  if (!/^\d+$/.test(s)) return NaN;
  return Number(s);
}

@Controller('api/v1')
export class FnSfr00107Controller {
  @Post('/tax-invoices/receive')
  @HttpCode(200)
  async receiveTaxInvoices(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const startDate = textOf(data['startDate']);
    const endDate = textOf(data['endDate']);
    if (!DATE_RE.test(startDate) || !DATE_RE.test(endDate)) {
      throw new ApiError(422, 'INVALID_DATE_RANGE', '조회 기간(시작일·종료일)을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT (CAST(:startDate AS date) > CAST(:endDate AS date)) AS "invalid"`,
        { startDate, endDate },
      );
      if (rows[0] && rows[0]['invalid']) {
        throw new ApiError(422, 'INVALID_DATE_RANGE', '시작일이 종료일보다 늦을 수 없습니다.');
      }
      // TODO: 국세청 홈택스 연동 모듈과 수신 데이터 형식이 입력에 없어 수신·저장을 구현하지 못했다.
      // 연동 모듈이 없는 동안에는 반영 없이 실패로 알린다 (수신 데이터를 반영하지 않는다).
      throw new ApiError(502, 'NTS_LINK_FAILED', '국세청 연동에 실패하여 수신 데이터를 반영하지 않았습니다.');
    });
  }

  @Get('/tax-invoices')
  async listTaxInvoices(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const q = checks.queryOf(req.query);
    const startDate = textOf(q['startDate']);
    const endDate = textOf(q['endDate']);
    if ((startDate !== '' && !DATE_RE.test(startDate)) || (endDate !== '' && !DATE_RE.test(endDate))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '날짜는 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const partnerId = wholeOf(q['partnerId']);
    const pageIn = wholeOf(q['page']);
    const sizeIn = wholeOf(q['size']);
    if (Number.isNaN(partnerId) || Number.isNaN(pageIn) || Number.isNaN(sizeIn)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '숫자 형식이 올바르지 않습니다.');
    }
    const page = pageIn === null ? 0 : pageIn;
    let size = sizeIn === null || sizeIn === 0 ? DEFAULT_SIZE : sizeIn;
    if (size > MAX_SIZE) size = MAX_SIZE;
    return transaction(async (db) => {
      const where = `WHERE (CAST(:startDate AS date) IS NULL OR issue_date >= CAST(:startDate AS date))
        AND (CAST(:endDate AS date) IS NULL OR issue_date <= CAST(:endDate AS date))
        AND (CAST(:partnerId AS bigint) IS NULL OR partner_id = CAST(:partnerId AS bigint))`;
      const filter = {
        startDate: startDate === '' ? null : startDate,
        endDate: endDate === '' ? null : endDate,
        partnerId: partnerId,
      };
      const items = await db.query(
        `SELECT tax_invoice_id AS "taxInvoiceId",
          approval_no AS "approvalNo",
          partner_id AS "partnerId",
          direction AS "direction",
          tax_type AS "taxType",
          issue_date AS "issueDate",
          supply_amount AS "supplyAmount",
          tax_amount AS "taxAmount"
        FROM tax_invoice
        ${where}
        ORDER BY issue_date DESC, tax_invoice_id DESC
        LIMIT :limit OFFSET :offset`,
        { ...filter, limit: size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM tax_invoice ${where}`,
        filter,
      );
      const total = Number(counts[0] ? counts[0]['total'] : 0);
      return {
        items: items.map((r: Record<string, unknown>) => ({
          ...r,
          taxInvoiceId: Number(r['taxInvoiceId']),
          partnerId: Number(r['partnerId']),
          supplyAmount: Number(r['supplyAmount']),
          taxAmount: Number(r['taxAmount']),
        })),
        page,
        size,
        total,
      };
    });
  }
}

