import { useState } from 'react';
import {
  call, useData, Badge, Num, DateText, Filters, Band, DataTable, Pager, Drawer,
  Tiles, Form, Field, DateInput, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Page, Row, Column } from '../kit';

const SIZE = 20;

export default function FnSfr00107Page({ role, notify }: PageProps) {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [opening, setOpening] = useState(false);
  const [rcvStart, setRcvStart] = useState('');
  const [rcvEnd, setRcvEnd] = useState('');
  const [result, setResult] = useState<Row | undefined>(undefined);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/tax-invoices', role, undefined, { ...applied, page, size: SIZE }),
    [applied, page, role],
  );

  const columns: Column[] = [
    { key: 'approvalNo', label: '승인번호' },
    { key: 'partnerId', label: '거래처', render: (r) => <RefName table="partner" role={role} value={r.partnerId} /> },
    { key: 'direction', label: '매출/매입 구분', render: (r) => <Badge value={r.direction} /> },
    { key: 'taxType', label: '과세·면세 구분', render: (r) => <Badge value={r.taxType} /> },
    { key: 'issueDate', label: '작성일자', render: (r) => <DateText value={r.issueDate} /> },
    { key: 'supplyAmount', label: '공급가액', render: (r) => <Num value={r.supplyAmount} /> },
    { key: 'taxAmount', label: '세액', render: (r) => <Num value={r.taxAmount} /> },
  ];

  const search = () => {
    setPage(0);
    setApplied({ startDate, endDate, partnerId });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setPartnerId('');
    setPage(0);
    setApplied({});
  };

  const openReceive = () => {
    setRcvStart('');
    setRcvEnd('');
    setResult(undefined);
    setOpening(true);
  };

  const receive = async () => {
    if (!rcvStart || !rcvEnd) {
      throw new Error('수신 시작일과 종료일을 입력해 주세요.');
    }
    if (rcvStart > rcvEnd) {
      throw new Error('시작일이 종료일보다 늦을 수 없습니다.');
    }
    const res = await call('POST', '/tax-invoices/receive', role, { startDate: rcvStart, endDate: rcvEnd });
    setResult(res);
    notify('전자세금계산서를 수신했습니다.');
    reload();
  };

  const reasons = result && Array.isArray(result.errorReasons) ? (result.errorReasons as unknown[]) : [];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>반영 건수</h2>
        <Tiles items={[['전자세금계산서', <Num value={data ? data.total : 0} />]]} />
      </section>
      <section className="box span-8">
        <h2>국세청 수신</h2>
        <Band>
          <button type="button" onClick={openReceive}>국세청 자료 수신</button>
        </Band>
      </section>
      <section className="box span-12">
        <h2>전자세금계산서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="발행일 시작">
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="발행일 종료">
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="거래처 ID">
            <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="전체" />
          </Field>
        </Filters>
        {error ? <ErrorText text={error} /> : null}
        <Band total={data ? data.total : 0} />
        <DataTable columns={columns} rows={data ? data.items : []} empty="수신된 전자세금계산서가 없습니다." />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {opening ? (
        <Drawer title="국세청 자료 수신" onClose={() => setOpening(false)}>
          <Form onSubmit={receive} submit="수신">
            <Field label="수신 시작일" required>
              <DateInput value={rcvStart} onChange={setRcvStart} />
            </Field>
            <Field label="수신 종료일" required>
              <DateInput value={rcvEnd} onChange={setRcvEnd} />
            </Field>
          </Form>
          {result ? (
            <div>
              <Tiles items={[['수신 건수', <Num value={result.receivedCount} />]]} />
              {reasons.length > 0 ? (
                <ul>
                  {reasons.map((reason, i) => (
                    <li key={i}>{String(reason)}</li>
                  ))}
                </ul>
              ) : null}
            </div>
          ) : null}
        </Drawer>
      ) : null}
    </div>
  );
}
